package com.vandorlabs.client;
import com.google.gson.*;
import com.vandorlabs.blocks.*;
import com.vandorlabs.tiles.*;
import net.minecraft.block.Block;
import net.minecraft.nbt.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
/** Actual renderer-facing selectors and block light, sampled without carrying or chip ownership. */
public final class ScreenAppearanceLegacyChecks {
 public static void main(String[] args)throws Exception{
  net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(TileEntityAnimatedScreenSelector.class,new ResourceLocation("minecraft:screen_appearance_reference"));JsonArray output=new JsonArray();int samples=0;
  for(String id:ScreenFamilyLegacyChecks.IDS){BlockAnimatedScreenSelector block=null;for(Block candidate:ModBlocks.BLOCKS)if(candidate.getRegistryName().getResourcePath().equals(id))block=(BlockAnimatedScreenSelector)candidate;
   for(int mode=-1;mode<3;mode++)for(int playback=0;playback<3;playback++)for(int invert=0;invert<2;invert++)for(int profile=0;profile<5;profile++){
    TileEntityAnimatedScreenSelector tile=(TileEntityAnimatedScreenSelector)block.createNewTileEntity(null,0);NBTTagCompound tag=tile.writeToNBT(new NBTTagCompound());tag.setBoolean("redstoneEnabled",(profile&1)!=0);tag.setBoolean("RedstoneInverted",invert!=0);tag.setInteger("displayMode",playback);tag.setInteger("animationSpeedIndex",profile%3);tag.setString("selectedScreen",ModBlocks.DISPLAY_SCREEN_IDS.get(profile*29%ModBlocks.DISPLAY_SCREEN_IDS.size()));tag.setString("inputPanel",TileEntityAnimatedScreenSelector.INPUT_PANELS[profile*37%TileEntityAnimatedScreenSelector.INPUT_PANELS.length]);tag.setString("secondaryInputPanel",TileEntityAnimatedScreenSelector.INPUT_PANELS[profile*53%TileEntityAnimatedScreenSelector.INPUT_PANELS.length]);tag.setBoolean("DisplaySplit",(profile&1)!=0);
    if(mode>=0){NBTTagCompound activation=new NBTTagCompound();activation.setInteger("Mode",mode);activation.setIntArray("Textures",profile==1?new int[]{-1,27,-1,484}:new int[]{-1,-1,-1,-1});activation.setIntArray("Playback",profile==1?new int[]{-1,2,1,-1}:new int[]{-1,-1,-1,-1});activation.setIntArray("Speeds",profile==1?new int[]{-1,2,-1,0}:new int[]{-1,-1,-1,-1});tag.setTag("DisplayActivation",activation);}else tag.removeTag("DisplayActivation");
    if(profile==2){NBTTagCompound rows=new NBTTagCompound();rows.setBoolean("Enabled",true);rows.setString("Title","Rows");rows.setTag("Rows",new NBTTagList());tag.setTag("RedstonePrimary",rows);}if(profile==3){NBTTagCompound rows=new NBTTagCompound();rows.setBoolean("Enabled",true);rows.setString("Title","Rows");rows.setTag("Rows",new NBTTagList());tag.setTag("RedstoneSecondary",rows);}if(profile==4){tag.setInteger("PrimarySurfaceTexture",27);tag.setInteger("SecondarySurfaceTexture",484);}
    tile.readFromNBT(tag);NonRenderingChecks.MemoryWorld world=new NonRenderingChecks.MemoryWorld(false);BlockPos pos=new BlockPos(0,80,0);world.states.put(pos,block.getDefaultState());tile.setWorld(world);tile.setPos(pos);world.tiles.put(pos,tile);JsonObject row=new JsonObject();row.addProperty("id",id);row.addProperty("saved",tile.writeToNBT(new NBTTagCompound()).toString());JsonArray powers=new JsonArray();for(int power=0;power<16;power++){tile.setChannelLevel(power);JsonArray values=new JsonArray();values.add(tile.activationMode());values.add(tile.activationState());values.add(tile.sharedArtworkTexture());values.add(tile.primaryArtworkTexture());values.add(tile.getEffectiveMode());values.add(tile.getAnimationSpeedIndex());values.add(tile.splitDisplay());values.add(tile.activationOverridesArtwork());for(int slot=0;slot<2;slot++){values.add(tile.getSurfaceTexture(slot));values.add(tile.effectiveMode(slot));values.add(tile.effectiveSpeed(slot));}values.add(block.getLightValue(block.getDefaultState(),world,pos));powers.add(values);samples++;}row.add("powers",powers);output.add(row);
   }
  }
  String serialized=output.toString();java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");StringBuilder digest=new StringBuilder();for(byte b:hash.digest(serialized.getBytes("UTF-8")))digest.append(String.format("%02x",b&255));if(!digest.toString().equals("f9a6a25b10b008b6009ce9641428ad3ede3d3cdefc4d13efc7c76fefb2aa710c"))throw new AssertionError("Actual Screen appearance changed "+digest);JsonObject reference=new JsonObject();reference.addProperty("sha256",digest.toString());reference.add("cases",output);java.nio.file.Path path=java.nio.file.Paths.get("build/test-artifacts/screen-appearance-reference.json");java.nio.file.Files.createDirectories(path.getParent());java.nio.file.Files.write(path,reference.toString().getBytes("UTF-8"));System.out.println("Actual Screen appearance reference PASS profiles="+output.size()+" powers="+samples+" sha256="+digest);
 }
}
